def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    total_opp_c = opp.count('C')
    total_opp_d = n - total_opp_c
    total_my_c = my.count('C')
    total_my_d = n - total_my_c

    w = n if n < 12 else 12
    recent_opp = opp[n - w:]
    recent_opp_c = recent_opp.count('C')
    recent_opp_d = w - recent_opp_c

    opp_last = opp[-1]
    my_last = my[-1]

    cC = 0
    cD = 0
    dC = 0
    dD = 0
    for i in range(1, n):
        if my[i - 1] == 'C':
            if opp[i] == 'C':
                cC += 1
            else:
                cD += 1
        else:
            if opp[i] == 'C':
                dC += 1
            else:
                dD += 1

    cc_total = cC + cD
    dc_total = dC + dD
    pC = cC / cc_total if cc_total else 0.5
    pD = dC / dc_total if dc_total else 0.5

    if total_opp_d == 0:
        if n < 5:
            return 'C'
        if total_my_d > (1 if my_last == 'D' else 0):
            return 'D'
        if my_last == 'D':
            return 'C'
        return 'D'

    if n >= 3 and total_opp_d == n:
        return 'D'

    if w >= 4 and recent_opp_c == 0:
        return 'D'

    if n < 8:
        if total_opp_d > total_opp_c + 3:
            return 'D'
        if opp_last == 'C':
            return 'C'
        if n >= 2 and my[n - 2] == 'D':
            return 'C'
        return 'D'

    recent_rate = recent_opp_c / w
    total_rate = total_opp_c / n

    if n == 98:
        if recent_rate < 0.55:
            return 'D'
        if dc_total >= 2 and pD <= 0.35 and recent_rate >= 0.65:
            return 'C'
        if dc_total >= 2 and pD >= 0.70 and recent_rate >= 0.70:
            return 'D'
        if recent_opp_c >= recent_opp_d:
            return 'C'
        return 'D'

    nonrecip = cc_total >= 3 and dc_total >= 3 and pD >= pC - 0.10 and pC < 0.90
    cooperative = recent_rate >= 0.60 and total_rate >= 0.45 and not nonrecip

    if not cooperative:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    if opp_last == 'C':
        if recent_rate >= 0.70 and total_rate >= 0.55:
            if dC >= 2 and dD == 0:
                return 'D'
            if dC >= 3 and dD <= 1 and rng.random() < 0.12:
                return 'D'
        return 'C'

    caused = n >= 2 and my[n - 2] == 'D'
    if (my_last == 'D' or caused) and recent_opp_c >= recent_opp_d:
        return 'C'

    return 'D'
